package model;
import java.sql.Timestamp;
public class Order { private int orderId; private String customerName,orderStatus; private double totalAmount; private Timestamp orderDate; public Order(){} public Order(int id,String n,double a,String s,Timestamp d){orderId=id;customerName=n;totalAmount=a;orderStatus=s;orderDate=d;} public int getOrderId(){return orderId;} public void setOrderId(int v){orderId=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public double getTotalAmount(){return totalAmount;} public void setTotalAmount(double v){totalAmount=v;} public String getOrderStatus(){return orderStatus;} public void setOrderStatus(String v){orderStatus=v;} public Timestamp getOrderDate(){return orderDate;} public void setOrderDate(Timestamp v){orderDate=v;} }
